spec.rawSql:
SELECT (ts AT TIME ZONE 'Asia/Tehran') AS time, price::float8 AS sell_fill
FROM pair_trade.fill
WHERE rotation_id = ${rotation} AND upper(side) = 'SELL';

SELECT (ts AT TIME ZONE 'Asia/Tehran') AS time, price::float8 AS buy_fill
FROM pair_trade.fill
WHERE rotation_id = ${rotation} AND upper(side) = 'BUY';
